//! Gold: `dw-model` bundle preparation is 1:1 with the live
//! `frontier_batch.prepare_batch_bundle`.
//!
//! `tests/fixtures/gold/model_bundle_v1.json` was generated by
//! `scripts/gold_model_bundle.py`: candidates constructed through the real
//! Pydantic models, the reference run end to end at a FIXED materialisation
//! root (`/tmp/gold_model_bundle_fixed`) because the digests cover
//! root-containing bytes. The test replays every case against the identical
//! tree at the identical path and compares the sealed artifacts byte for
//! byte, plus modes (0444 files, 0555 dir) and the exact error strings.
//!
//! Traps pinned: exclusive destination, candidate-identity re-derivation,
//! duplicate ids, evidence resolution (missing / not-regular / outside-roots
//! / SHA mismatch — with macOS `/private` partial-resolution in errno
//! messages), spend-cap arithmetic with Python `.6f` messages, empty-batch
//! guard, and the manifest's sorted indent-2 JSON with Python float repr.

#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::indexing_slicing,
    clippy::too_many_lines,
    clippy::doc_markdown,
    clippy::panic,
    clippy::cast_possible_truncation,
    clippy::redundant_closure,
    reason = "gold tests assert on their own fixtures"
)]

use std::os::unix::fs::PermissionsExt as _;
use std::path::{Path, PathBuf};

use serde_json::Value;

use dw_model::{prepare_batch_bundle, BundleSpec};

fn gold_path() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    while !dir.join("tests/fixtures/gold").is_dir() {
        assert!(dir.pop(), "could not locate tests/fixtures/gold");
    }
    dir.join("tests/fixtures/gold/model_bundle_v1.json")
}

fn gold() -> Value {
    serde_json::from_str(&std::fs::read_to_string(gold_path()).unwrap()).unwrap()
}

/// Remove a root, unlocking sealed bundles (0555/0444) on the way — the
/// reference's own error path does the same.
fn wipe(root: &Path) {
    let _ = std::fs::remove_dir_all(root);
    if root.exists() {
        unlock_tree(root);
        let _ = std::fs::remove_dir_all(root);
    }
}

fn unlock_tree(root: &Path) {
    let mut stack = vec![root.to_path_buf()];
    while let Some(dir) = stack.pop() {
        if let Ok(entries) = std::fs::read_dir(&dir) {
            for entry in entries.flatten() {
                let path = entry.path();
                if path.is_dir() {
                    let _ = std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o755));
                    stack.push(path);
                } else {
                    let _ = std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o644));
                }
            }
        }
    }
    let _ = std::fs::set_permissions(root, std::fs::Permissions::from_mode(0o755));
}

fn write_tree(root: &Path, files: &[Value]) {
    for entry in files {
        let rel = entry["rel"].as_str().unwrap();
        let target = root.join(rel);
        std::fs::create_dir_all(target.parent().unwrap()).unwrap();
        let bytes: Vec<u8> = entry["bytes"]
            .as_array()
            .unwrap()
            .iter()
            .map(|b| b.as_u64().unwrap() as u8)
            .collect();
        std::fs::write(target, bytes).unwrap();
    }
}

fn mode_of(path: &Path) -> u32 {
    std::fs::metadata(path).unwrap().permissions().mode() & 0o777
}

/// Both tests materialise the same fixed root; they must not interleave
/// (a sealed 0555 bundle from one test breaks the other's rename).
static ROOT_GUARD: std::sync::Mutex<()> = std::sync::Mutex::new(());

#[test]
fn every_case_matches_the_live_reference() {
    let _guard = ROOT_GUARD
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    let g = gold();
    let fixed_root = PathBuf::from(g["fixed_root"].as_str().unwrap());
    let alt_root = PathBuf::from(g["alt_root"].as_str().unwrap());
    let alt_file = &g["alt_file"];

    let mut happy = 0usize;
    let mut errors = 0usize;
    for case in g["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let input = &case["input"];

        wipe(&fixed_root);
        wipe(&alt_root);
        write_tree(&fixed_root, input["files"].as_array().unwrap());
        write_tree(&alt_root, std::slice::from_ref(alt_file));

        let dest = fixed_root.join(input["dest_rel"].as_str().unwrap());
        if input
            .get("precreate_dest")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        {
            std::fs::create_dir_all(&dest).unwrap();
        }

        let roots: Vec<PathBuf> = vec![fixed_root.clone()];
        let no_candidates: Vec<Value> = Vec::new();
        let candidates: &[Value] = input["candidates"]
            .as_array()
            .map_or(no_candidates.as_slice(), Vec::as_slice);
        let spec = BundleSpec {
            destination: &dest,
            candidates,
            model: input["model"].as_str().unwrap(),
            allowed_roots: roots.as_slice(),
            input_price_per_million: input["input_price_per_million"].as_f64().unwrap(),
            output_price_per_million: input["output_price_per_million"].as_f64().unwrap(),
            batch_discount: input["batch_discount"].as_f64().unwrap(),
            spend_cap_usd: input["spend_cap_usd"].as_f64().unwrap(),
            created_at: input["created_at"].as_str().unwrap(),
        };

        match case["kind"].as_str().unwrap() {
            "happy" => {
                let manifest = prepare_batch_bundle(&spec)
                    .unwrap_or_else(|e| panic!("case {name}: unexpected error {e}"));
                assert_eq!(
                    manifest,
                    serde_json::from_str::<Value>(case["expected"]["manifest"].as_str().unwrap())
                        .unwrap(),
                    "case {name}: returned manifest"
                );
                for artifact in ["manifest.json", "candidates.jsonl", "requests.jsonl"] {
                    let got = std::fs::read_to_string(dest.join(artifact)).unwrap();
                    let want = case["expected"][match artifact {
                        "manifest.json" => "manifest",
                        "candidates.jsonl" => "candidates",
                        _ => "requests",
                    }]
                    .as_str()
                    .unwrap();
                    assert_eq!(got, want, "case {name}: {artifact} bytes");
                    assert_eq!(
                        mode_of(&dest.join(artifact)),
                        0o444,
                        "case {name}: {artifact} mode"
                    );
                }
                assert_eq!(mode_of(&dest), 0o555, "case {name}: bundle dir mode");
                let leftovers: Vec<String> = std::fs::read_dir(&fixed_root)
                    .unwrap()
                    .flatten()
                    .map(|e| e.file_name().to_string_lossy().into_owned())
                    .filter(|n| n.starts_with('.'))
                    .collect();
                assert!(
                    leftovers.is_empty(),
                    "case {name}: staging left {leftovers:?}"
                );
                happy += 1;
            }
            "error" => {
                let error = prepare_batch_bundle(&spec)
                    .err()
                    .unwrap_or_else(|| panic!("case {name}: expected an error"));
                // The gold prefixes the exception class; the Rust error
                // carries only the message.
                let want = case["expected_msg"]
                    .as_str()
                    .unwrap()
                    .split_once(": ")
                    .map_or(case["expected_msg"].as_str().unwrap(), |(_, message)| {
                        message
                    });
                assert_eq!(error.to_string(), want, "case {name}: message");
                let dest_absent = !dest.exists();
                assert_eq!(
                    dest_absent,
                    case["dest_absent_after"].as_bool().unwrap_or(true),
                    "case {name}: destination presence after failure"
                );
                let leftovers: Vec<String> = std::fs::read_dir(&fixed_root)
                    .unwrap()
                    .flatten()
                    .map(|e| e.file_name().to_string_lossy().into_owned())
                    .filter(|n| n.starts_with('.'))
                    .collect();
                assert!(
                    leftovers.is_empty(),
                    "case {name}: staging left {leftovers:?}"
                );
                errors += 1;
            }
            other => panic!("unknown case kind {other}"),
        }
    }
    assert_eq!(happy + errors, g["cases"].as_array().unwrap().len());
}

/// Negative control: a sealed bundle resists modification and deletion —
/// the write-once property the `_write`/chmod protocol exists for.
#[test]
fn sealed_bundle_is_write_once() {
    let _guard = ROOT_GUARD
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    let g = gold();
    let fixed_root = PathBuf::from(g["fixed_root"].as_str().unwrap());
    let alt_root = PathBuf::from(g["alt_root"].as_str().unwrap());
    wipe(&fixed_root);
    wipe(&alt_root);
    write_tree(
        &fixed_root,
        g["cases"][0]["input"]["files"].as_array().unwrap(),
    );
    write_tree(&alt_root, std::slice::from_ref(&g["alt_file"]));

    let candidates: Vec<Value> = g["cases"][0]["input"]["candidates"]
        .as_array()
        .cloned()
        .unwrap_or_default();
    let input = &g["cases"][0]["input"];
    let dest = fixed_root.join(input["dest_rel"].as_str().unwrap());
    let sealed_roots: Vec<PathBuf> = vec![fixed_root.clone()];
    let spec = BundleSpec {
        destination: &dest,
        candidates: &candidates,
        model: input["model"].as_str().unwrap(),
        allowed_roots: sealed_roots.as_slice(),
        input_price_per_million: input["input_price_per_million"].as_f64().unwrap(),
        output_price_per_million: input["output_price_per_million"].as_f64().unwrap(),
        batch_discount: input["batch_discount"].as_f64().unwrap(),
        spend_cap_usd: input["spend_cap_usd"].as_f64().unwrap(),
        created_at: input["created_at"].as_str().unwrap(),
    };
    prepare_batch_bundle(&spec).expect("seals");

    // Second preparation to the same destination must fail closed.
    let again = prepare_batch_bundle(&spec);
    assert!(again.is_err(), "re-preparation must be refused");
    assert!(again
        .unwrap_err()
        .to_string()
        .starts_with("batch bundle already exists"));

    // And a plain rmtree fails on the read-only tree (the generator itself
    // tripped on this): the sealed dir does not grant write permission.
    let naive = std::fs::remove_dir_all(&dest);
    assert!(
        naive.is_err(),
        "naive remove_dir_all must fail on a sealed bundle"
    );
    unlock_tree(&dest);
    let _ = std::fs::remove_dir_all(&dest);
}
